<?= $this->extend('auth/layout') ?><?= $this->section('content') ?><?php $v=session()->getFlashdata('assistance_form')??[];?><p class="muted">Use this form only when Student Records could not verify your registration. Student Records will review your evidence and contact you outside this system.</p><form method="post" enctype="multipart/form-data" action="<?= site_url('verification-assistance') ?>"><?= csrf_field() ?><label>Student ID<input name="student_id" required maxlength="30" value="<?= esc($v['student_id']??'','attr') ?>"></label><label>Full name<input name="full_name" required maxlength="150" value="<?= esc($v['full_name']??'','attr') ?>"></label><label>Contact email<input type="email" name="contact_email" required maxlength="150" value="<?= esc($v['contact_email']??'','attr') ?>"></label><label>Program<input name="program" required maxlength="150" value="<?= esc($v['program']??'','attr') ?>"></label><label>Explanation<textarea name="explanation" required maxlength="2000" rows="5"><?= esc($v['explanation']??'') ?></textarea></label><label>Supporting document (PDF, JPG, or PNG; maximum 5 MiB)<input type="file" name="supporting_document" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" required></label><button>Submit request</button></form><p class="switch"><a href="<?= site_url('register') ?>">Back to registration</a></p><?= $this->endSection() ?>
